-- Уникальность ledger; запрет повторного event_id с другим JSON и разных event_id для одной версии сущности.
WITH history AS (SELECT event_id,event_type,entity_id,entity_version,event_document AS document FROM {{target:oil_dds__event}} UNION ALL SELECT event_id,event_type,entity_id,entity_version,event_json AS document FROM {{target:oil_stg__v_event_parsed}}) SELECT count(*) AS n FROM (SELECT event_id AS k FROM {{target:oil_dds__event}} GROUP BY event_id HAVING event_id IS NULL OR count(*)>1 UNION ALL SELECT event_id AS k FROM history GROUP BY event_id HAVING count(DISTINCT document)>1 OR count_if(document IS NULL)>0 UNION ALL SELECT min(event_id) AS k FROM history GROUP BY event_type,entity_id,entity_version HAVING event_type IS NULL OR entity_id IS NULL OR entity_version IS NULL OR count(DISTINCT event_id)>1) q;
